// Production keys and passwords (WP18). Generated locally with node:crypto,
// stored in Secret Manager once and never regenerated by a later deploy
// (rotating the ticket key would invalidate every ticket in flight; rotating
// the session key signs everyone out; the save key would orphan every local
// profile's saves). Formats match the Go services: Ed25519 keys are base64
// (standard alphabet) of the 32-byte seed / 32-byte public key.
import crypto from 'node:crypto';

function b64urlToStd(s) {
  return Buffer.from(s, 'base64url').toString('base64');
}

/** An Ed25519 key pair as the services read it. */
export function ed25519Pair() {
  const { privateKey, publicKey } = crypto.generateKeyPairSync('ed25519');
  const priv = privateKey.export({ format: 'jwk' });
  const pub = publicKey.export({ format: 'jwk' });
  return { seed: b64urlToStd(priv.d), pub: b64urlToStd(pub.x) };
}

/** URL- and env-file-safe random token. */
export function token(bytes = 24) {
  return crypto.randomBytes(bytes).toString('hex');
}

/**
 * Every secret the deployment uses: Secret Manager name -> how to make it.
 * Pairs are generated together so the public half always matches.
 * `external` secrets are never generated; the deploy prints how to add them.
 */
export function secretSpecs() {
  return [
    { name: 'lodestone-ticket-private-key', pair: 'ticket', half: 'seed', env: 'LODESTONE_TICKET_PRIVATE_KEY' },
    { name: 'lodestone-ticket-public-key', pair: 'ticket', half: 'pub', env: 'LODESTONE_TICKET_PUBLIC_KEY' },
    { name: 'lodestone-session-private-key', pair: 'session', half: 'seed', env: 'LODESTONE_SESSION_PRIVATE_KEY' },
    { name: 'lodestone-session-public-key', pair: 'session', half: 'pub', env: 'LODESTONE_SESSION_PUBLIC_KEY' },
    { name: 'lodestone-save-private-key', pair: 'save', half: 'seed', env: 'LODESTONE_SAVE_PRIVATE_KEY' },
    { name: 'lodestone-save-public-key', pair: 'save', half: 'pub', env: 'LODESTONE_SAVE_PUBLIC_KEY' },
    { name: 'lodestone-pg-password', gen: () => token(24), env: 'POSTGRES_PASSWORD' },
    { name: 'lodestone-livekit-key', gen: () => 'lk' + token(8), env: 'LODESTONE_LIVEKIT_KEY' },
    { name: 'lodestone-livekit-secret', gen: () => token(32), env: 'LODESTONE_LIVEKIT_SECRET' },
    { name: 'lodestone-wake-cron-token', gen: () => token(24), env: 'LODESTONE_WAKE_CRON_TOKEN' },
    { name: 'lodestone-metrics-token', gen: () => token(24), env: 'LODESTONE_METRICS_TOKEN' },
    { name: 'lodestone-creator-token', gen: () => token(24), env: 'LODESTONE_CREATOR_TOKEN' },
    { name: 'lodestone-anthropic-api-key', external: true, env: 'ANTHROPIC_API_KEY' },
  ];
}

/** Generate values for the given specs (pairs share one key pair). */
export function generate(specs) {
  const pairs = {};
  const out = {};
  for (const s of specs) {
    if (s.external) continue;
    if (s.pair) {
      pairs[s.pair] ??= ed25519Pair();
      out[s.name] = pairs[s.pair][s.half];
    } else {
      out[s.name] = s.gen();
    }
  }
  return out;
}
